generate.initial_sparql:
PREFIX schema1: <http://schema.org/>

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasInvestmentGoal ?goal ;
       wm:hasRebalancingAction ?ra ;
       wm:hasPortfolioHealth ?ph ;
       wm:hasSectorAllocation ?sa ;
       wm:hasScenarioRebalancing ?sr .

  ?goal wm:investmentGoal ?goalLabel .
  FILTER(CONTAINS(LCASE(STR(?goalLabel)), "retirement planning"))

  ?ra wm:action ?raAction .
  FILTER(CONTAINS(LCASE(STR(?raAction)), "de-risking"))

  ?ph wm:diversificationScore ?divScore .
  FILTER(xsd:decimal(?divScore) < 25)

  ?sa wm:sector ?sectorLabel .
  FILTER(CONTAINS(LCASE(STR(?sectorLabel)), "technology"))

  ?sr wm:hasMarketScenario ?ms .
  ?ms rdfs:label ?msLabel .
  FILTER(CONTAINS(LCASE(STR(?msLabel)), "bear market"))
}

